  $q=$pdo->prepare("SELECT COUNT(*) FROM candidates c JOIN positions p ON p.id=c.position_id WHERE p.election_id=? AND c.approval_status='pending'");$q->execute([$id]);$pendingCount=(int)$q->fetchColumn();
  if(!$positionCount||$missingCandidates)throw new RuntimeException('Add at least one approved candidate for every position before opening the election.');
