 $s=$pdo->prepare('UPDATE elections SET status=? WHERE id=?');$s->execute([$status,$id]);audit('election_status_changed','Election #'.$id.' → '.$status);flash('success','Election status updated.');redirect('index.php?page=manage');
case 'verify':require_role(['admin','officer']);$id=(int)$_POST['id'];$s=db()->prepare("UPDATE users SET is_verified=1 WHERE id=? AND role='student'");$s->execute([$id]);audit('voter_verified','Student #'.$id);flash('success','Student voter verified.');redirect('index.php?page=manage');
case 'create-officer':require_role(['admin']);$name=trim($_POST['full_name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pw=$_POST['password']??'';if(!$name||!$email||strlen($pw)<12)throw new RuntimeException('Enter valid details and a password of at least 12 characters.');$s=db()->prepare("INSERT INTO users(full_name,email,password_hash,role,is_verified,email_verified_at) VALUES(?,?,?,'officer',1,NOW())");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);audit('officer_created',$email);flash('success','Electoral officer account created.');redirect('index.php?page=manage');
case 'export':require_role(['admin','officer']);$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT title,status FROM elections WHERE id=?');$q->execute([$id]);$el=$q->fetch();if(!$el)throw new RuntimeException('Election not found.');if($el['status']!=='closed')throw new RuntimeException('Results can only be exported after the election is closed.');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="nacos-election-'.$id.'-report.csv"');$out=fopen('php://output','w');fputcsv($out,['Election',$el['title']]);fputcsv($out,['Position','Candidate','Votes','Percentage']);$ps=db()->prepare('SELECT * FROM positions WHERE election_id=? ORDER BY sort_order,id');$ps->execute([$id]);foreach($ps as $p){$q=db()->prepare("SELECT c.full_name,COALESCE(v.vote_count,0) votes FROM candidates c LEFT JOIN votes v ON v.candidate_id=c.id AND v.election_id=? AND v.position_id=? WHERE c.position_id=? AND c.approval_status='approved' ORDER BY votes DESC");$q->execute([$id,$p['id'],$p['id']]);$rows=$q->fetchAll();$total=array_sum(array_column($rows,'votes'));foreach($rows as $r)fputcsv($out,[$p['title'],$r['full_name'],$r['votes'],$total?round($r['votes']/$total*100,2):0]);}fclose($out);exit;
case 'reports':require_role(['admin','officer']);page_title('Election reports');?><div class="d-flex justify-content-between mb-4"><div><div class="eyebrow">Election intelligence</div><h2 class="section-title">Reports & audit trail</h2></div><button class="btn btn-outline-primary no-print" onclick="window.print()">Print this report</button></div><?php foreach(db()->query('SELECT * FROM elections ORDER BY created_at DESC') as $el):?><div class="card p-4 mb-3"><div class="d-flex justify-content-between"><h5 class="fw-bold"><?=e($el['title'])?></h5><span class="badge text-bg-secondary"><?=e($el['status'])?></span></div><div class="small text-secondary mb-2"><?=e($el['starts_at'])?> — <?=e($el['ends_at'])?></div><?php $q=db()->prepare('SELECT COUNT(*) FROM voter_participation WHERE election_id=?');$q->execute([$el['id']]);?><p class="mb-2">Total ballots recorded: <strong><?=number_format((int)$q->fetchColumn())?></strong></p><?php if($el['status']==='closed'):?><a href="index.php?page=results&id=<?=$el['id']?>" class="btn btn-sm btn-outline-primary">View detailed results</a> <a href="index.php?page=export&id=<?=$el['id']?>" class="btn btn-sm btn-outline-secondary">Download CSV</a><?php else:?><span class="text-secondary small">Results are hidden until the election is closed.</span><?php endif;?></div><?php endforeach;?><div class="card p-4"><h5 class="fw-bold">Recent audit activity</h5><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Details</th></tr></thead><tbody><?php $logs=db()->query('SELECT a.*,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 100')->fetchAll();foreach($logs as $l):?><tr><td class="small text-nowrap"><?=e($l['created_at'])?></td><td><?=e($l['full_name']??'System')?></td><td><?=e($l['action'])?></td><td><?=e($l['details'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php render_footer();break;
default: http_response_code(404);page_title('Not found');?><div class="card empty">Page not found. <a href="index.php">Return home</a>.</div><?php render_footer();
